import sys

def main():
    data = sys.stdin.read().split()
    n = int(data[0])
    first = {0: 0}
    s = 0
    best = 0
    for i in range(1, n + 1):
        s += int(data[i])
        if s in first:
            if i - first[s] > best:
                best = i - first[s]
        else:
            first[s] = i
    print(best)

main()

